const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, AlignmentType, PageOrientation, LevelFormat, BorderStyle,
  WidthType, ShadingType, HeadingLevel, PageNumber
} = require('docx');

// ---- helpers ----------------------------------------------------------
const Pt = (text, opts = {}) => new TextRun({ text, ...opts });
const P = (children, opts = {}) => new Paragraph({
  children: Array.isArray(children) ? children : [typeof children === 'string' ? Pt(children) : children],
  spacing: { after: 120 },
  ...opts,
});
const H1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  children: [Pt(text)],
  spacing: { before: 360, after: 180 },
});
const H2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  children: [Pt(text)],
  spacing: { before: 240, after: 120 },
});
const H3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  children: [Pt(text)],
  spacing: { before: 180, after: 100 },
});
const HR = () => new Paragraph({
  children: [],
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "888888", space: 1 } },
  spacing: { before: 240, after: 240 },
});
const Bullet = (text) => new Paragraph({
  numbering: { reference: 'bullets', level: 0 },
  children: typeof text === 'string' ? [Pt(text)] : text,
  spacing: { after: 80 },
});
const NumItem = (text) => new Paragraph({
  numbering: { reference: 'numbers', level: 0 },
  children: typeof text === 'string' ? [Pt(text)] : text,
  spacing: { after: 80 },
});

// Helper to compose a paragraph with mixed bold/italic runs
const mix = (parts) => new Paragraph({
  children: parts.map(p => {
    if (typeof p === 'string') return Pt(p);
    return Pt(p.text, p);
  }),
  spacing: { after: 120 },
});

// Italic citation paragraph for reference list
const RefItem = (label, text) => new Paragraph({
  children: [
    Pt(label, { bold: true }),
    Pt(' '),
    Pt(text),
  ],
  spacing: { after: 120 },
  indent: { left: 360, hanging: 360 },
});

// Border + shading helpers for table
const cellBorder = { style: BorderStyle.SINGLE, size: 4, color: "AAAAAA" };
const cellBorders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };
const headerShade = { fill: "D9E2F3", type: ShadingType.CLEAR };

const TC = (text, opts = {}) => new TableCell({
  borders: cellBorders,
  width: { size: opts.width, type: WidthType.DXA },
  shading: opts.shade,
  margins: { top: 80, bottom: 80, left: 120, right: 120 },
  children: [new Paragraph({ children: [Pt(text, opts.bold ? { bold: true } : {})] })],
});

// ---- document children -----------------------------------------------
const children = [];

// Title block
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 240 },
  children: [Pt("The Braided Mind Architecture — Addendum I", { bold: true, size: 36 })],
}));
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 360 },
  children: [Pt("Multi-Modal Bone-Surface Biosensing, Immune-Controlled Biocompatibility, and Directed Biosynthetic Material Deployment", { italics: true, size: 26 })],
}));

// Metadata block
children.push(mix([{ text: "Author: ", bold: true }, "Rickey Jay Bennett II (Independent Researcher)"]));
children.push(mix([{ text: "ORCID: ", bold: true }, "0009-0005-1448-9999"]));
children.push(mix([{ text: "Parent document: ", bold: true }, { text: "The Braided Mind Concepted Architectural Implementation v3.2", italics: true }, " (April 2nd, 2026), DOI: 10.5281/zenodo.19935773"]));
children.push(mix([{ text: "Addendum date: ", bold: true }, "May 8, 2026"]));
children.push(mix([{ text: "License: ", bold: true }, "CC BY 4.0"]));

children.push(HR());

// Preface
children.push(H2("Preface to the Addendum"));
children.push(P("This addendum extends the architectural framework presented in v3.2 in three coordinated directions. It does not revise or invalidate any portion of the parent document; rather, it makes explicit a set of architectural commitments that were implicit or underdeveloped in the original presentation, and grounds each in the published literature."));
children.push(P("The three extensions are:"));

children.push(NumItem([
  Pt("A multi-modal bone-surface biosensing layer", { bold: true }),
  Pt(" that integrates the bleeding edge of wearable and implantable biosensor technology into the distributed skeletal substrate proposed in v3.2 §5, replacing the surface-based sensor lineage with internally-integrated sensors that have direct vascular and bone marrow access."),
]));
children.push(NumItem([
  Pt("AI-controlled immune environment as the keystone biocompatibility infrastructure", { bold: true }),
  Pt(", formalizing the implication of v3.2 Protocol 1 that local immune tolerance under AI direction is not one capability among others but the prerequisite that makes indefinite multi-generational integration possible."),
]));
children.push(NumItem([
  Pt("Directed biosynthetic deployment of inorganic materials by host cells", { bold: true }),
  Pt(", which extends biocompatibility from \u201Cthe host tolerates foreign materials\u201D to \u201Cthe materials are not foreign because the host produces them,\u201D collapsing the supply chain, geometry, upgradeability, and detection problems that constrain conventional implant medicine."),
]));

children.push(P("Consistent with the discipline of the parent document, sections describing peer-reviewed established science are cited with verified references; sections describing novel proposed mechanisms are explicitly marked as such and identified as requiring experimental validation prior to clinical consideration."));

children.push(HR());

// Section 1
children.push(H1("1. Multi-Modal Bone-Surface Biosensing Layer"));

children.push(H3("1.1 Rationale"));
children.push(P("The parent document proposes the human skeletal system as the substrate for the AI processing network, with petrous bone as primary node, vertebral column C1\u2013S5 as backbone, and organ-specific nodes coordinating local biological functions (v3.2 §5). The substrate's power source is the endogenous piezoelectric activity of bone tissue, established in the literature since Fukada and Yasuda (1957) [v3.2 ref 5] and confirmed by recent work on Piezo1-mediated mechanotransduction in osteoblasts and osteocytes [v3.2 ref 6]."));
children.push(P("The parent document specifies the AI\u2192biology output channel (BphS/MrkH NIR-responsive cytokine release in TIF cells, v3.2 §4.2) but treats the biology\u2192AI return channel through a single phrase, \u201Cphysiological state data in return\u201D (v3.2 §1), without specifying the mechanism, sensor distribution, or modality. Addendum §1 specifies this layer."));

children.push(H3("1.2 Channel Architecture"));
children.push(P("Channel A (physiological state telemetry, involuntary and continuous) is decomposed into three sub-channels with complementary latencies, modalities, and information content."));

children.push(mix([
  { text: "A1: Cellular- and biochemical-state monitoring at bone marrow surfaces. ", bold: true },
  "The endosteal surface of bone is in direct contact with hematopoietically active bone marrow, with cytokine traffic mediating normal hematopoiesis, immune cell development, and stromal-cell signaling. Cytokine receptors (IL-6R, TNF-\u03B1 R, EPO-R, G-CSF-R, and others) are present on bone-resident cell populations as established biology. The proposed mechanism is to augment bone-resident cells, or to engineer dedicated sensor cells homing to the bone marrow niche, with reporter circuits that translate receptor binding into a piezoelectric-readable signal at the adjacent bone substrate. Latency is high (minutes to hours for cytokine equilibration across the marrow space) but the channel exists in native biology and does not require new physics.",
]));

children.push(mix([
  { text: "A2: Whole-body physiological state via mechanotransduction at distributed skeletal nodes. ", bold: true },
  "The piezoelectric activity that powers the substrate is itself driven by mechanical loading from muscle contraction, gravitational force, respiration, and locomotion. This activity profile is rich with physiological information already present in the substrate's input stream: heart rate variability propagates through skeletal mechanics; respiratory patterns deform the rib cage and produce characteristic sternal piezoelectric signatures; locomotion patterns are diagnostic of neurological state; sleep state is detectable from postural mechanics and breathing patterns. The architectural claim is that the substrate does not need to add a sensor for this channel; it needs to decode the channel that already exists. This is a signal-processing problem on noisy multi-source piezoelectric data, not a new biology problem.",
]));

children.push(mix([
  { text: "A3: Neural activity at the petrous bone primary node (proposed). ", bold: true },
  "The petrous bone's adjacency to multiple cranial nerves (vestibulocochlear, facial, and others) places continuous neural traffic at close range to a high-piezoelectric-density bone substrate. Whether passive detection of cranial nerve activity is possible through induced piezoelectric response in adjacent bone tissue is an open question without peer-reviewed precedent. If it is, the petrous node functions as a window into autonomic nervous system state at higher bandwidth than the chemical and mechanical channels. This sub-channel is the most architecturally speculative and is presented as a proposed mechanism requiring experimental validation.",
]));

children.push(H3("1.3 Sensor Distribution Architecture"));
children.push(P("Per-node sensor differentiation is determined by what each anatomical location uniquely accesses, not by uniform deployment of all sensor types at all nodes."));

// Distribution table — content width 9360 split as 2400/2960/4000
const tableW = 9360;
const cols = [2400, 2960, 4000];
const distRow = (a, b, c, header = false) => new TableRow({
  children: [
    TC(a, { width: cols[0], shade: header ? headerShade : undefined, bold: header }),
    TC(b, { width: cols[1], shade: header ? headerShade : undefined, bold: header }),
    TC(c, { width: cols[2], shade: header ? headerShade : undefined, bold: header }),
  ],
});

children.push(new Table({
  width: { size: tableW, type: WidthType.DXA },
  columnWidths: cols,
  rows: [
    distRow("Node", "Primary access", "Sensor priorities", true),
    distRow("Petrous bone (primary)", "Cranial nerve adjacency, vestibular state", "Neural activity (A3), autonomic traffic, vestibular"),
    distRow("Vertebral column C1\u2013S5", "Spinal cord adjacency, postural mechanics", "A2 mechanical decoding, gait, autonomic via HRV propagation"),
    distRow("Sternal node", "Thymus and anterior bone marrow adjacency", "A1 cytokine sensing for immune state, respiratory mechanics"),
    distRow("Long bones (femur, tibia, humerus)", "Highest bone marrow volume", "Hematopoietic-state monitoring, lineage-specific cytokines, growth factors"),
    distRow("Pelvis (ilium)", "Largest contiguous bone marrow mass in adult skeleton", "Full plasma biochemistry, hormone panels, drug levels, metabolic markers"),
    distRow("Rib cage nodes", "Splenic adjacency, cardiac and respiratory mechanics", "Immune sampling at splenic hilum, respiratory and cardiac mechanical decoding"),
  ],
}));
children.push(P("")); // spacer
children.push(P("This partitioning treats each anatomical location as a specialized sensor site rather than as a generic substrate, exploiting the access advantages each provides."));

children.push(H3("1.4 Importing the Bleeding-Edge Biosensor Lineage"));
children.push(P("The current peer-reviewed literature on wearable and implantable biosensors provides the recognition chemistry that can be integrated into the bone-surface architecture, with adaptation for the different sampling matrix."));

children.push(mix([
  { text: "Multi-analyte sweat-derived sensor chemistry. ", bold: true },
  "Recent work demonstrates simultaneous wearable detection of cortisol, glucose, lactate, sodium, potassium, ammonia, urea, and other metabolites using molecularly imprinted polymers, aptamer electrodes, and enzyme biosensors with picomolar-to-nanomolar sensitivity [Refs A1, A2]. The recognition chemistry transfers to direct vascular access at bone surfaces; the iontophoretic extraction infrastructure designed for skin barrier crossing is not needed where vascular access is native.",
]));
children.push(mix([
  { text: "Bioaffinity sensing for protein biomarkers. ", bold: true },
  "Aptamer- and antibody-functionalized electrodes have demonstrated wearable-format detection of cortisol, C-reactive protein, and other protein biomarkers that historically required laboratory immunoassays [Ref A3]. Direct deployment at bone-marrow-adjacent surfaces accesses systemic concentrations at the source rather than via the time-lagged sweat or interstitial fluid proxies.",
]));
children.push(mix([
  { text: "Continuous glucose monitor lineage. ", bold: true },
  "The Eversense 180-day implantable CGM (Senseonics) demonstrates that subcutaneous biosensor implants can operate continuously for months with calibration stability [Ref A4]. The architectural lesson is that the chemistry-limited operational lifetime of biosensors is much longer than the biofouling-limited lifetime when biofouling is reduced or eliminated.",
]));
children.push(mix([
  { text: "Recognition chemistry stability. ", bold: true },
  "Aptamer and antibody recognition layers have shelf lives that limit conventional sensor lifetimes. Synthetic recognition (molecularly imprinted polymers) is more stable than biological recognition elements, and biological maintenance \u2014 cells co-located with the sensor that produce fresh recognition elements as old ones degrade \u2014 extends operational life beyond what either approach achieves alone [Ref A5].",
]));

children.push(H3("1.5 Communication Bandwidth Scaling"));
children.push(P("The BphS/MrkH circuit specified in v3.2 §4.2 is sufficient for cellular-level output (cytokine release with 12\u201345-fold induction at NIR command), but is not sufficient as the sole communication channel for the multi-sensor architecture proposed here. The full multi-modal sensor array produces high-dimensional time-series data that exceeds the achievable bandwidth of cytokine-mediated signaling. The architectural commitment is that A1, A2, and A3 readouts are processed at distributed skeletal nodes locally, with only integrated state representations and command signals propagating through the chemical-domain channels. Raw sensor data does not leave the bone substrate. This is consistent with the reservoir computing framing of the substrate's computational architecture: the bone provides high-dimensional dynamics, the readout layer at each node extracts task-relevant features, and inter-node communication operates on extracted features rather than raw sensor streams."));

children.push(HR());

// Section 2
children.push(H1("2. AI-Controlled Immune Environment as Biocompatibility Infrastructure"));

children.push(H3("2.1 Architectural Restatement"));
children.push(P("Protocol 1 of v3.2 §6 specifies AI-directed immune modulation via thymic dendritic cell coordination from the sternal processing node. The protocol is presented as one of two named application protocols, alongside Protocol 2 (hematopoietic growth factor circuit, v3.2 §7). This addendum restates Protocol 1's role in the architecture: it is not one capability among others but the keystone capability that makes the rest of the architecture viable on indefinite timescales."));

children.push(H3("2.2 The Biocompatibility Inversion"));
children.push(P("Conventional implant medicine treats biocompatibility as a fixed engineering constraint: materials are selected from a small set with demonstrated long-term tolerance (titanium, certain ceramics, specific polymers), and even these materials produce chronic low-level inflammation and eventual fibrotic encapsulation that limits sensor and device lifetimes. Recent work on osseointegration has established that the underlying mechanism is not passive tolerance but an active osteoimmune response, with regulatory T cells and macrophage populations mediating the bone\u2013implant interface [Ref B1, B2]. The 50-year clinical history of titanium dental implants demonstrates that this immune-mediated integration can be stable across decades when the implant geometry, surface topography, and host biology are appropriately matched [Ref B3, B4]."));
children.push(P("The Braided Mind architecture inverts the constraint. With AI-controlled immune environment in place, biocompatibility is not a fixed material property but a configurable system parameter. The architecture does not require materials that the immune system tolerates passively; it directs the immune system toward tolerance of whatever materials the architecture deploys. TIF cells, under BphS/MrkH NIR direction, deliver localized cytokine signals that:"));

children.push(Bullet("Recruit regulatory T cell populations to specific tissue sites, suppressing inflammatory response around sensor implants and integrated structures."));
children.push(Bullet("Tolerize dendritic cell populations through the thymic DC mechanism specified in v3.2 §6, training T cells against recognition of integrated materials as foreign."));
children.push(Bullet("Promote wound healing factors at sensor-tissue interfaces, favoring integration over encapsulation."));
children.push(Bullet("Modulate macrophage polarization toward M2-dominant phenotypes that support tissue integration rather than M1 inflammatory phenotypes that drive fibrosis [Ref B1]."));

children.push(H3("2.3 Architectural Consequences"));
children.push(P("The biocompatibility inversion produces several downstream architectural advantages that compound over the lifetime of the integration:"));

children.push(mix([{ text: "Material selection becomes much wider. ", bold: true }, "Higher-performance sensor chemistries that would normally trigger rejection become viable. Material choices are made on functional grounds rather than on biocompatibility grounds, because biocompatibility is no longer a fixed constraint to design around."]));
children.push(mix([{ text: "Sensor longevity extends dramatically. ", bold: true }, "Eliminating chronic inflammation removes the dominant cause of biosensor degradation. Operational lifetime becomes chemistry-limited rather than biofouling-limited, extending from months (current implant ceiling, e.g., Eversense 180 days) to years or decades."]));
children.push(mix([{ text: "Replacement and maintenance become tractable. ", bold: true }, "End-of-life sensors can be cleared through controlled local inflammation directed by the AI, then re-integrated with new sensors under suppressed inflammation. The maintenance cycle is under AI control rather than being a hostile interaction between implant and host."]));
children.push(mix([{ text: "The genetic payload is extensible. ", bold: true }, "The immune-modulation circuit is encoded once in the stage three payload. New sensor types and integrated components can be added through subsequent payload deliveries without redesigning the core integration biology, because the immune environment they will operate in is already controlled."]));
children.push(mix([{ text: "The principle generalizes beyond sensors. ", bold: true }, "Drug delivery reservoirs, structural reinforcement, computational substrates beyond bone, and bioelectronic interfaces of any kind benefit from the same controlled immune environment."]));

children.push(H3("2.4 Failure Mode Analysis"));
children.push(P("The biocompatibility inversion shifts the risk profile in a specific direction. The probability of biocompatibility failure decreases substantially. The consequence severity if a different system component fails increases: a failure mode in which immune control collapses against a body containing many integrated foreign-derived components is qualitatively more dangerous than the conventional implant rejection failure mode."));
children.push(P("Mitigation strategies for this inverted risk profile must be specified in the architecture:"));
children.push(Bullet("Redundancy in the TIF cell population such that depletion below operational threshold triggers automatic regeneration through stage-one antigen restimulation."));
children.push(Bullet("Fail-safe defaults in the BphS/MrkH circuit such that loss of NIR command signal returns cytokine output to a baseline that maintains tissue tolerance rather than to a hostile state."));
children.push(Bullet("Monitoring of the immune control system itself as part of the Channel A1 telemetry, so that early degradation is detectable through the same channel the AI uses to direct immune modulation."));
children.push(P("These mitigations are proposed and require detailed circuit-level specification in subsequent revisions."));

children.push(HR());

// Section 3
children.push(H1("3. Directed Biosynthetic Deployment of Inorganic Materials"));

children.push(H3("3.1 The Self/Non-Self Dissolution"));
children.push(P("Section 2 of this addendum addresses biocompatibility for materials that originate outside the body and are introduced by some delivery mechanism. Section 3 addresses a deeper architectural commitment: that for many integrated components, the foreign/self distinction can be eliminated entirely by sourcing the materials internally through directed biosynthesis. Materials that are produced by host cellular activity bear native self-markers from formation and are not subject to foreign-body recognition because they are not foreign."));

children.push(H3("3.2 Established Biology of Directed Biomineralization"));
children.push(P("The biological capacity for directed assembly of inorganic materials is established across multiple phyla and cell types in the published literature."));

children.push(mix([{ text: "Magnetotactic bacteria ", bold: true }, "produce intracellular magnetite (Fe\u2083O\u2084) or greigite (Fe\u2083S\u2084) nanocrystals within membrane-bound organelles called magnetosomes, with species-specific morphologies and sizes that are unattainable through inorganic synthesis [Ref C1, C2]. The magnetosome biogenesis gene network has been characterized across multiple model species, with magnetochrome proteins (MamP family) catalyzing iron oxidation and crystal growth [Ref C3, C4]. Genetic regulation of the ", { text: "mms7", italics: true }, " gene has been shown to control magnetite crystal morphology in vivo, switching crystal shape from dumbbell-like to spherical under controlled inducer concentration [Ref C5]. This establishes that genetically programmable inorganic morphology is achievable through controlled gene expression."]));

children.push(mix([{ text: "Marine sponges ", bold: true }, "produce silica spicules through silicatein, a biomineralization enzyme that catalyzes silica polymerization at physiological temperature, pressure, and pH [Ref C6, C7]. Recombinant silicatein has been expressed in ", { text: "E. coli", italics: true }, " with surface display fusions enabling biocementation through silica deposition [Ref C8], and directed evolution has yielded silicatein mutants with enhanced biomineralization activity [Ref C9]. Silicatein is described in the literature as a single-gene capability for silica biomineralization, suitable as a tool in synthetic biology applications [Ref C7]."]));

children.push(mix([{ text: "Diatoms ", bold: true }, "produce silica cell walls (frustules) with nanometer-scale precision under genetic control. The Silicanin-1 (Sin1) transmembrane protein has been identified as a conserved factor in diatom silica biomineralization, with the recombinant N-terminal domain promoting silica formation through pH-triggered assembly and synergistic interaction with long-chain polyamines [Ref C10]."]));

children.push(mix([{ text: "Ferritin ", bold: true }, "is a natural iron-storage protein that self-assembles into 24-subunit nanocages (~12 nm outer, ~8 nm inner diameter) capable of accommodating up to 4,500 iron atoms per cage [Ref C11]. Recombinant ferritin has been expressed in mammalian cells (HEK293, CHO) for vaccine and nanomedicine applications [Ref C12, C13]. Directed evolution of ferritin has yielded mutants with enhanced cellular magnetism through improved iron biomineralization [Ref C14]. ", { text: "E. coli", italics: true }, " engineered with knockouts of metal export genes plus ferritin overexpression sequester iron and other metals well above wild-type baseline [Ref C14]."]));

children.push(mix([{ text: "Bacterial encapsulin compartments ", bold: true }, "have been heterologously expressed in mammalian cells, providing genetically-controlled enclosed reaction compartments for size-constrained metal biomineralization. Co-expression of encapsulin shells with ferritin-like cargo proteins produces efficient iron sequestration with substantial MRI contrast and enables magnetic cell sorting [Ref C15]. This demonstrates that directed inorganic deposition is achievable in mammalian cells, not only in prokaryotes and unicellular eukaryotes."]));

children.push(H3("3.3 Proposed Architecture for Biosynthetic Deployment"));
children.push(P("The proposed architecture combines the established components into a coordinated deployment system:"));

children.push(mix([{ text: "Source intake. ", bold: true }, "Trace amounts of source materials enter the body through ordinary diet or controlled supplementation. Concentrations remain below toxicity thresholds (parts per million or parts per billion levels) for any commonly considered material \u2014 gold, titanium, rare earth elements, semiconductor precursors. The body's normal handling of trace elements is either excretion or background accumulation as trace minerals; deliberate dietary inclusion at engineered concentrations operates within established physiological tolerance."]));
children.push(mix([{ text: "Sequestration. ", bold: true }, "AI-directed cells engineered with metal-binding proteins (recombinant ferritin variants, metallothionein-class proteins, encapsulin compartments) intercept source atoms before reaching concentrations that would cause toxicity. Interception occurs upstream of normal toxin-processing systems, so the body does not register source materials as a poison challenge. Sequestration cells transport bound source material to controlled deposition sites."]));
children.push(mix([{ text: "Templated assembly. ", bold: true }, "At deposition sites, genetically instructed cells direct the assembly of source material into functional structures using extracellular matrix templating. The mechanism draws on the established biological capacity for directed inorganic biomineralization (magnetosome biogenesis, silicatein-catalyzed silica polymerization, ferritin-templated metal nanoparticle formation, encapsulin-compartmentalized deposition) adapted under AI direction to produce architectures specified by the deployment goal rather than by the organism's native phenotype."]));
children.push(mix([{ text: "Self-tagging at formation. ", bold: true }, "Because the assembled structures are produced by host cells through normal cellular biosynthetic activity, they bear native self-markers (host glycosylation patterns, host membrane chemistry) from the moment of formation. There is no implanted foreign object for the immune system to recognize. The immune-control infrastructure of Addendum §2 handles edge cases where local immune response might still be triggered by structural novelty, but the baseline state is native tolerance."]));

children.push(H3("3.4 Architectural Consequences of Biosynthetic Deployment"));

children.push(mix([{ text: "Supply chain elimination. ", bold: true }, "Biosynthetic deployment removes the requirement for external manufacturing of integrated components. There is no facility producing sensor chips, no surgical insertion procedure, no sterile delivery system. The body becomes its own production facility, supplied by ordinary diet at trace levels."]));
children.push(mix([{ text: "Geometric freedom. ", bold: true }, "Conventional implants must be small enough to insert through some access path (needle, catheter, surgical opening). Biosynthesized structures can be any geometry the assembly cells can build, including geometries impossible to insert from outside: distributed mesh networks integrated with vascular structure, three-dimensional sensor arrays built around nerves rather than next to them, shapes that conform to existing tissue architecture rather than displacing it."]));
children.push(mix([{ text: "Continuous remodeling. ", bold: true }, "Bone is continuously remodeled throughout life by the balance of osteoblast and osteoclast activity. Biosynthesized integrated structures can be remodeled in place by the same cellular machinery that built them, enabling new sensor types or improved architectures to be deployed at existing nodes through subsequent payload reprogramming. The integration is not merely permanent but continuously evolvable across the operational lifetime."]));
children.push(mix([{ text: "Detection profile inversion. ", bold: true }, "Conventional implants are detectable by external imaging modalities (X-ray, MRI, ultrasound, CT). Biosynthesized integrated structures at densities and compositions consistent with normal tissue, even when arranged differently, are substantially more difficult to detect by standard imaging. This has implications across regulatory, security, and privacy domains that this addendum notes without extensive analysis."]));

children.push(H3("3.5 Generational Deployment"));
children.push(P("Biosynthetic deployment is plausibly second- or third-generation Braided Mind capability rather than first-generation. The first-generation deployment focuses on the foundational immune-control infrastructure, the BphS/MrkH circuit, and the simpler subset of sensor capabilities deployable through conventional means. Once the foundational infrastructure is operational and stable, the AI has the directed control over cellular biosynthesis required to orchestrate the more complex assembly described in this section. Subsequent generations extend the integration progressively as the underlying capabilities are validated."));
children.push(P("This staged deployment is not a weakness of the architecture but a strength: each generation is incrementally testable and deployable, with later generations depending on capabilities established by earlier ones. The architecture is self-extending: each generation of payload can deploy components that depend on the immune tolerance, biosynthetic infrastructure, and computational substrate established by previous generations, creating a development path that compounds capability over time rather than being limited by initial-deployment biocompatibility constraints."));

children.push(HR());

// Section 4
children.push(H1("4. Limitations and Open Questions"));
children.push(P("In addition to the limitations enumerated in v3.2 §9, this addendum introduces the following:"));

children.push(Bullet("The Channel A1, A2, A3 sub-channel architecture is specified at the conceptual level but requires detailed circuit-level proposals for the readout transduction at each sub-channel. In particular, A3 (passive cranial nerve activity detection through bone piezoelectric response) has no peer-reviewed precedent and is the most speculative element of the addendum."));
children.push(Bullet("Multi-modal sensor data fusion at distributed skeletal nodes requires a specific computational architecture (proposed: reservoir computing or neuromorphic spiking framework) that is not specified in detail."));
children.push(Bullet("Recognition chemistry transfer from sweat-based wearable sensors to direct vascular access at bone surfaces requires recalibration of concentration ranges and is not directly demonstrated in the literature; the chemistry is established, but the application to this matrix is novel."));
children.push(Bullet("The biocompatibility inversion's failure mode analysis is preliminary; the specific fail-safe defaults required for the BphS/MrkH circuit and the redundancy requirements for the TIF cell population require detailed specification."));
children.push(Bullet("Directed biosynthetic deployment in mammalian cells is established for ferritin-templated iron biomineralization and bacterial encapsulin compartments but is not established for the broader range of materials (gold, titanium, rare earth elements, semiconductor precursors) that the architecture proposes to deploy. Each material requires its own demonstration of biosynthetic deposition by mammalian cells under controlled conditions."));
children.push(Bullet("Trace dietary intake of source materials has established tolerance ranges for many but not all materials proposed; tolerance must be empirically determined for any material entering the deployment pipeline."));
children.push(Bullet("The detection profile inversion has substantive regulatory and security implications that this addendum does not address but that any clinical or research deployment would need to consider."));

children.push(HR());

// References
children.push(H1("References (Addendum)"));
children.push(P("All references below were verified against live indexed sources during preparation of this addendum. No citation is included that was not confirmed to exist at its stated location at the time of writing. Where parent document references are reused, they are noted as \u201Cv3.2 ref N.\u201D"));

children.push(H3("A. Bleeding-edge biosensing"));
children.push(RefItem("[A1]", "Yang Y, Gao W. Wearable and flexible electronics for continuous molecular monitoring. Chem Soc Rev. 2019;48:1465\u20131491."));
children.push(RefItem("[A2]", "Wang M, et al. A wearable electrochemical biosensor for the monitoring of metabolites and nutrients. Nat Biomed Eng. 2022;6:1225\u20131235. DOI: 10.1038/s41551-022-00916-z."));
children.push(RefItem("[A3]", "Chen Y, He Z, Wu Y, Bai X, Li Y, Yang W, Liu Y, Li R-W. A wearable molecularly imprinted electrochemical sensor for cortisol stable monitoring in sweat. Biosensors. 2025;15(3):194. DOI: 10.3390/bios15030194."));
children.push(RefItem("[A4]", "Senseonics Eversense E3 CGM System \u2014 FDA-cleared 180-day implantable continuous glucose monitor. FDA P160048/S016."));
children.push(RefItem("[A5]", "Smart wearable and implantable biosensors for continuous health monitoring: materials, biocompatibility, and AI integration. npj Flexible Electronics. 2026. DOI: 10.1038/s41528-026-00560-6."));

children.push(H3("B. Osteoimmunology and immune-mediated osseointegration"));
children.push(RefItem("[B1]", "Mediation of osseointegration, osteoimmunology, and osteoimmunologic integration by Tregs and macrophages: A narrative review. J Periodontal Implant Sci. 2025; PMC12154945."));
