children.push(RefItem("[C8]", "Surface-displayed silicatein-\u03B1 enzyme in bioengineered E. coli enables biocementation and silica mineralization. Front Bioeng Biotechnol. 2025; PMC12341959."));
children.push(RefItem("[C9]", "Directed evolution of silicatein reveals biomineralization synergism between protein sequences. ACS Omega. 2024. DOI: 10.1021/acsomega.4c06359."));
children.push(RefItem("[C10]", "Kotzsch A, et al. Silicanin-1 is a conserved diatom membrane protein involved in silica biomineralization. BMC Biology. 2017;15:65. DOI: 10.1186/s12915-017-0400-8."));
children.push(RefItem("[C11]", "Recombinant ferritins for multimodal nanomedicine. PMC10236959."));
children.push(RefItem("[C12]", "Self-assembled ferritin nanoparticles for delivery of antigens and development of vaccines. PMC11397193."));
