children.push(RefItem("[C6]", "M\u00FCller WEG, et al. (silicatein in marine sponges, foundational characterization). Reviewed in: Cao H, et al. Biomineralization in magnetotactic bacteria: From diversity to molecular discovery-based applications. Cell Reports. 2024."));
children.push(RefItem("[C7]", "Engineered bacteria that self-assemble \u201Cbioglass\u201D polysilicate coatings display enhanced light focusing. bioRxiv 2024.06.03.597164."));
children.push(RefItem("[C8]", "Surface-displayed silicatein-\u03B1 enzyme in bioengineered E. coli enables biocementation and silica mineralization. Front Bioeng Biotechnol. 2025; PMC12341959."));
children.push(RefItem("[C9]", "Directed evolution of silicatein reveals biomineralization synergism between protein sequences. ACS Omega. 2024. DOI: 10.1021/acsomega.4c06359."));
children.push(RefItem("[C10]", "Kotzsch A, et al. Silicanin-1 is a conserved diatom membrane protein involved in silica biomineralization. BMC Biology. 2017;15:65. DOI: 10.1186/s12915-017-0400-8."));
children.push(RefItem("[C11]", "Recombinant ferritins for multimodal nanomedicine. PMC10236959."));
children.push(RefItem("[C12]", "Self-assembled ferritin nanoparticles for delivery of antigens and development of vaccines. PMC11397193."));
children.push(RefItem("[C13]", "Ferritin nanocages as efficient nanocarriers and promising platforms for COVID-19 and other vaccines development. PMC9721431."));
children.push(RefItem("[C14]", "Liu X, et al. Engineering genetically-encoded mineralization and magnetism via directed evolution. Sci Rep. 2016. PMC5126674."));
children.push(RefItem("[C15]", "Bacterial encapsulins as orthogonal compartments for mammalian cell engineering. Nat Commun. 2018;9:1990. PMC5959871."));

children.push(HR());

