const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, AlignmentType, LevelFormat, BorderStyle,
  WidthType, ShadingType, HeadingLevel
} = require('docx');

// ---- helpers ----------------------------------------------------------
const Pt = (text, opts = {}) => new TextRun({ text, ...opts });
const P = (children, opts = {}) => new Paragraph({
  children: Array.isArray(children) ? children : [typeof children === 'string' ? Pt(children) : children],
  spacing: { after: 120 },
  ...opts,
});
const H1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  children: [Pt(text)],
  spacing: { before: 360, after: 180 },
});
const H2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  children: [Pt(text)],
  spacing: { before: 240, after: 120 },
});
const H3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  children: [Pt(text)],
  spacing: { before: 180, after: 100 },
});
const H4 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_4,
  children: [Pt(text)],
  spacing: { before: 140, after: 80 },
});
const HR = () => new Paragraph({
  children: [],
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "888888", space: 1 } },
  spacing: { before: 240, after: 240 },
});
const Bullet = (text) => new Paragraph({
  numbering: { reference: 'bullets', level: 0 },
  children: typeof text === 'string' ? [Pt(text)] : text,
  spacing: { after: 80 },
});
const NumItem = (text) => new Paragraph({
  numbering: { reference: 'numbers', level: 0 },
  children: typeof text === 'string' ? [Pt(text)] : text,
  spacing: { after: 80 },
});

// Helper to compose a paragraph with mixed bold/italic runs
const mix = (parts) => new Paragraph({
  children: parts.map(p => {
    if (typeof p === 'string') return Pt(p);
    return Pt(p.text, p);
  }),
  spacing: { after: 120 },
});

// Italic citation paragraph for reference list
const RefItem = (label, text) => new Paragraph({
  children: [
    Pt(label, { bold: true }),
    Pt(' '),
    Pt(text),
  ],
  spacing: { after: 120 },
  indent: { left: 360, hanging: 360 },
});

// Border + shading helpers for table
const cellBorder = { style: BorderStyle.SINGLE, size: 4, color: "AAAAAA" };
const cellBorders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };
const headerShade = { fill: "D9E2F3", type: ShadingType.CLEAR };

const TC = (text, opts = {}) => new TableCell({
  borders: cellBorders,
  width: { size: opts.width, type: WidthType.DXA },
  shading: opts.shade,
  margins: { top: 80, bottom: 80, left: 120, right: 120 },
  children: [new Paragraph({ children: [Pt(text, opts.bold ? { bold: true } : {})] })],
});

// ---- document children -----------------------------------------------
const children = [];

// Title block
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 240 },
  children: [Pt("The Braided Mind Architecture — Addendum II", { bold: true, size: 36 })],
}));
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 360 },
  children: [Pt("Energy Management Infrastructure, Operational Floor Analysis, and Failsafe Maintenance Subsystem", { italics: true, size: 26 })],
}));

// Metadata block
children.push(mix([{ text: "Author: ", bold: true }, "Rickey Jay Bennett II (Independent Researcher)"]));
children.push(mix([{ text: "ORCID: ", bold: true }, "0009-0005-1448-9999"]));
children.push(mix([{ text: "Parent document: ", bold: true }, { text: "The Braided Mind Concepted Architectural Implementation v3.2", italics: true }, " (April 2nd, 2026), DOI: 10.5281/zenodo.19935773"]));
children.push(mix([{ text: "Companion addendum: ", bold: true }, { text: "The Braided Mind Architecture — Addendum I", italics: true }, " (May 8, 2026)"]));
children.push(mix([{ text: "Addendum date: ", bold: true }, "May 8, 2026"]));
children.push(mix([{ text: "Designation: ", bold: true }, "v3.4"]));
children.push(mix([{ text: "License: ", bold: true }, "CC BY 4.0"]));

children.push(HR());

// Preface
children.push(H2("Preface to Addendum II"));
children.push(P("This addendum extends the Braided Mind architecture along a third axis not addressed in v3.2 or in Addendum I: the energy budget of the integrated system across operational contexts, and the failure-mode architecture that determines what happens when that budget is not met. Where v3.2 specifies the substrate's primary power source (endogenous piezoelectric activity of bone tissue) and Addendum I specifies the sensor, immune-control, and biosynthetic infrastructure, Addendum II specifies the power generation, storage, safety, and preservation infrastructure that allow the integration to operate continuously across active periods, sleep, environmental disconnection, and emergency states."));
children.push(P("The four extensions presented here are:"));

children.push(NumItem([
  Pt("A multi-source energy generation architecture", { bold: true }),
  Pt(" combining piezoelectric activity, wireless inductive charging, internal storage, and metabolically up-regulated mitochondrial output, each fitted to specific operational contexts with documented switching logic."),
]));
children.push(NumItem([
  Pt("Distributed biosynthesized energy storage", { bold: true }),
  Pt(" providing surge handling, charging buffer, and reserve capacity, with explicit thermal safety architecture preventing wireless charging from becoming a hazard."),
]));
children.push(NumItem([
  Pt("A formal operational floor analysis", { bold: true }),
  Pt(" identifying five distinct failure thresholds with documented detection and response protocols, replacing the implicit single-failure framing of v3.2."),
]));
children.push(NumItem([
  Pt("A failsafe maintenance subsystem", { bold: true }),
  Pt(" implemented as gene-circuit logic rather than AI-directed compute, providing an unconditional baseline that preserves integration viability independent of the AI layer and converts the architecture's irrecoverable failure modes into recoverable dormancy states."),
]));

children.push(P("Consistent with the discipline of v3.2 and Addendum I, sections describing peer-reviewed established science are cited with verified references at the granularity the literature supports, with each component fact mapped to its specific source. Sections describing novel proposed mechanisms are explicitly marked as such and identified as requiring experimental validation prior to clinical consideration."));

children.push(HR());

// ============= Section 1 =============
children.push(H1("1. Multi-Source Energy Generation Architecture"));

children.push(H3("1.1 The Energy Budget Problem"));
children.push(P("The parent document (v3.2 §5.1) specifies the substrate's power source as the endogenous piezoelectric activity of bone tissue, with mechanical deformation generating electrical polarization across the collagen fiber matrix [v3.2 ref 5]. Bone's piezoelectric properties have been characterized continuously since Fukada and Yasuda (1957) and the Piezo1 mechanosensitive ion channel pathway in osteoblasts and osteocytes provides the cellular-level mechanism by which mechanical loading produces downstream signaling [v3.2 ref 6]."));
children.push(P("The architecture's reliance on piezoelectric activity creates a structural energy budget problem the parent paper does not address. Mechanical loading varies substantially across operational contexts: high during locomotion and active periods, moderate during seated activity, low during quiet wakefulness, very low during sleep, near-zero during deep sedentary states. Power generation tracks loading, which means substrate output drops during exactly the periods when the integrated AI most plausibly performs computationally intensive operations such as memory consolidation, learning updates, and integration of accumulated sensor data. A single-source piezoelectric architecture cannot operate continuously across the full diurnal cycle without either external power supplementation or substantial computational throttling during low-loading periods."));
children.push(P("Addendum II §1 specifies a four-source architecture in which piezoelectric activity remains the primary source during active periods and is supplemented by three additional sources fitted to specific operational contexts."));

children.push(H3("1.2 Source A: Piezoelectric Activity (Primary, Active Periods)"));
children.push(P("This source is specified in v3.2 §5 and is unchanged in Addendum II. The piezoelectric output of the skeletal substrate continues to power the architecture during active periods when mechanical loading is sufficient. The specifications in v3.2 §5.2 regarding primary nodes (petrous bone), vertebral backbone (C1\u2013S5), organ-specific nodes (sternal, rib cage), and full skeletal distribution apply without modification."));

children.push(H3("1.3 Source B: Wireless Inductive Charging (Primary, Sleep and Sedentary Periods)"));

children.push(H4("1.3.1 Established Technology Foundation"));
children.push(P("Wireless power transfer (WPT) for implantable medical devices is mature peer-reviewed engineering. Comprehensive reviews characterize the available WPT modalities for implantable devices, including capacitive coupling, non-radiative inductive coupling (NRIC), magnetic resonance coupling, ultrasonic transfer, and optical methods [Ref D1, D2]. Inductive coupling is the oldest and most clinically established technique, with applications dating to powering of artificial hearts in the 1960s and continuing through cochlear implants, neural stimulators, and modern continuous glucose monitor systems [Ref D1]. The fundamental physics \u2014 a primary coil generating an oscillating magnetic field that induces current in a secondary coil at appropriate resonant frequency \u2014 is well-characterized, and commercial Qi-standard wireless charging at 110\u2013205 kHz plus higher-frequency resonant systems at 6.78 MHz are deployed in consumer electronics, automotive, and medical contexts [Ref D1, D3]."));
children.push(P("The state of the art for miniaturized implantable devices is reviewed in [Ref D4], which addresses the challenge of delivering useful power to deep-tissue implants without exceeding tissue safety limits. Current research is extending operating frequencies and exploring alternative modalities (acoustic, magnetoelectric) specifically to maintain SAR compliance at higher delivered power [Ref D3, D4]."));

children.push(H4("1.3.2 Tissue Safety Constraints"));
children.push(P("Specific Absorption Rate (SAR) standards for human exposure to RF fields are established by IEEE C95.1 and ICNIRP guidelines. The IEEE C95.1-1999 standard sets local SAR limits at 1.6 W/kg averaged over 1 g of tissue; the IEEE C95.1-2005 update revised this to 2 W/kg averaged over 10 g of tissue; the IEEE C95.1-2019 standard refines exposure reference levels and dosimetric reference limits across the relevant frequency range [Ref D5, D6]. Whole-body average SAR limits are 4 W/kg for body exposure and 3.2 W/kg for head exposure under IEC 60601-2-33 [Ref D7]. ICNIRP and FCC guidelines historically derive from the same threshold determination that potentially harmful biological effects occur at whole-body SAR levels of 4 W/kg [Ref D8]."));
children.push(P("Direct measurements of RF heating in the presence of metallic medical implants have demonstrated that local SAR can substantially exceed nominal whole-body limits at implant sites \u2014 measured local SAR of 24.6 W/kg with associated 4.22\u00B0C temperature elevation in the tail region of artificial hip joints during 1.5T MRI scanning [Ref D7]. This establishes that any WPT architecture involving metallic receiver structures within the body must specifically address local SAR enhancement at the receiver, not only whole-body average SAR."));
children.push(P("For neural-adjacent implants the safety constraint is tighter still. RF-induced heating studies in intracranial electrode arrays demonstrate that head-transmit-receive coils at 2.4 W/kg head-average SAR produce maximum temperature changes below 1\u00B0C at 1.5T but elevated temperatures up to 2\u00B0C at 3T under standard conditions, with substantially higher excursions under fault conditions where lead terminations are electrically shorted [Ref D9]."));

children.push(H4("1.3.3 Architectural Application"));
children.push(P("The wireless charging source in the Braided Mind architecture deploys receiver coils through the biosynthetic deployment infrastructure specified in Addendum I §3. Engineered cells deposit conductive metal (gold, copper, or alloyed metal nanoparticles, sequestered through ferritin-class proteins per Addendum I refs C11, C14) in coil geometries within the bone substrate, sized to resonate at the carrier frequency of the external charger. Because the coils are biosynthesized from trace dietary inputs and tagged self at formation, they avoid the foreign-body response that conventional implanted coils encounter [Addendum I §2, §3]."));
children.push(P("External charging hardware is conventional: bed surfaces, recliners, and chairs incorporate transmitter coils using standard resonant inductive coupling at sub-MHz frequencies. The choice of operating frequency in the sub-MHz range is deliberate \u2014 lower frequencies penetrate tissue with reduced attenuation and produce lower SAR per unit delivered power [Ref D3, D10]. The 6.78 MHz ISM band used in higher-frequency consumer wireless charging is also viable but produces higher local SAR for equivalent delivered power and is reserved for shorter-range high-efficiency applications."));
children.push(P("Receiver placement in the architecture follows a routing constraint motivated by the local-SAR concern: charging coils are placed at sites distant from sensitive neural structures. Pelvic bone, long bones (femur, tibia, humerus), and sternal node receive the primary charging coils. The petrous bone primary node (v3.2 §5.2) does not host charging coils. Power transmitted through the conductive properties of the skeletal substrate to processing nodes occurs after voltage conditioning and at low currents that do not produce significant local heating."));

children.push(H4("1.3.4 Switching Logic"));
children.push(P("The AI layer monitors substrate energy state through Channel A2 telemetry (mechanical decoding at distributed skeletal nodes per Addendum I §1.2) and storage levels (capacitive readout, specified in §2 of this addendum). When piezoelectric output drops below a defined threshold and external charging field is detected at receiver coils, the AI switches power management to wireless-primary mode. Piezoelectric output continues to be harvested at whatever rate the residual mechanical loading provides; wireless charging supplements to meet operational demand."));
children.push(P("The AI also schedules computationally intensive operations to wireless-primary periods. Memory consolidation, learning updates, biosynthetic remodeling cycles, and other high-power tasks are deferred to sleep and sedentary periods when the system has access to external power. Active periods run in piezoelectric-primary mode with reduced computational load, prioritizing real-time sensor monitoring and immune-control modulation over deferable processing."));

children.push(H3("1.4 Source C: Biosynthesized Energy Storage (Buffer and Reserve)"));
children.push(P("This source is specified in §2 of this addendum and provides surge handling, charging buffer, and reserve capacity rather than serving as a primary generation source. Brief reference here: storage components draw from any active source (piezoelectric or wireless), retain energy as capacitive charge or chemical state, and discharge to maintain operation during transient mismatches between generation and demand or during periods when no active source is available."));

children.push(H3("1.5 Source D: Metabolic Up-Regulation via Mitochondrial Pathway (Reserve, Disconnected Operation)"));

children.push(H4("1.5.1 Mitochondrial Bioenergetics Foundation"));
children.push(P("Cellular ATP production in mammalian tissues occurs predominantly through oxidative phosphorylation in mitochondria, with the electron transport chain (ETC) coupling electron flow from NADH and FADH2 substrates to proton pumping across the inner mitochondrial membrane [Ref E1, E2]. The mammalian ETC comprises complexes I\u2013IV plus the mobile electron carriers ubiquinone and cytochrome c, with electron transfer through the complexes coupled to proton translocation that establishes a transmembrane electrochemical gradient [Ref E1]. The mitochondrial membrane potential (\u0394\u03A8m) maintained by this gradient drives ATP synthase (Complex V) to produce ATP from ADP and inorganic phosphate, with optimal \u0394\u03A8m range of approximately 80\u2013120 mV for efficient ATP synthesis with minimal reactive oxygen species generation [Ref E3]."));
children.push(P("This electron flow is itself an electrical current at cellular scale. The substrate architecture proposed here does not require conversion of ATP to electricity \u2014 it requires tapping the electrical activity that is already occurring during ATP production. The proton gradient, the electron flux through the ETC complexes, and the membrane potential are all directly electrical phenomena at the inner mitochondrial membrane."));

children.push(H4("1.5.2 Microbial Extracellular Electron Transfer as Architectural Template"));
children.push(mix([
  Pt("The biological capacity to conduct electrons from intracellular metabolism to extracellular acceptors is established in microbial bioelectrochemistry. "),
  Pt("Geobacter", { italics: true }),
  Pt(" and "),
  Pt("Shewanella", { italics: true }),
  Pt(" species perform extracellular electron transfer (EET) as a metabolic strategy, conducting electrons from internal metabolic processes to external mineral or electrode acceptors through specialized cellular structures [Ref F1, F2]. "),
  Pt("Geobacter sulfurreducens", { italics: true }),
  Pt(" electrically conductive pili (e-pili) are protein filaments that serve as conductive nanowires extending from the cell surface, with characterized genetic basis and structural features [Ref F3, F4]. "),
  Pt("Shewanella", { italics: true }),
  Pt(" species use a combination of outer-membrane c-type cytochromes and conductive nanowires for similar function [Ref F1, F4]. The genes encoding these electron-transfer capabilities have been characterized at sequence and structural level and have been heterologously expressed in other organisms [Ref F1, F4]."),
]));
children.push(P("The proposed architectural application in Addendum II is the engineering of cells co-located with mitochondria-rich populations in bone marrow that express microbial EET machinery (or eukaryotic equivalents derived from cytochrome electron transfer chains) to harvest a fraction of mitochondrial electron output during up-regulated activity. The cells do not replace mitochondria; they conduct a small fraction of the surplus electron flow during periods of metabolic up-regulation to the substrate's electrical network."));
children.push(P("This is presented as a proposed mechanism. The constituent biology \u2014 mitochondrial electron flow, microbial EET, heterologous expression of EET machinery \u2014 is established. The integration of these elements into an AI-directed mitochondrial energy harvesting system in mammalian tissue has no peer-reviewed experimental precedent."));

children.push(H4("1.5.3 Metabolic Up-Regulation Signaling"));
children.push(P("Direction of mitochondrial activity from the AI layer requires signaling through pathways that the body's existing metabolic regulation already responds to. The principal pathways are well-characterized:"));
children.push(P("PGC-1\u03B1 (peroxisome proliferator-activated receptor gamma coactivator 1-alpha) is the master regulator of mitochondrial biogenesis, controlling the transcription of mitochondrial components and oxidative metabolism through interactions with multiple nuclear receptors and transcription factors [Ref G1, G2, G3]. PGC-1\u03B1 expression and activity are modulated by AMPK, SIRT1, and a range of upstream signals including thyroid hormone receptor, PPAR\u03B3, and adrenergic stimulation [Ref G1, G4]. Forced overexpression of PGC-1\u03B1 activates mitochondrial biogenesis and increases oxidative capacity in multiple cell types [Ref G2, G3]."));
children.push(P("AMP-activated protein kinase (AMPK) is the cellular energy sensor that detects falling cellular energy status through increases in AMP:ATP and ADP:ATP ratios and activates catabolic pathways including mitochondrial biogenesis to restore energy balance [Ref H1, H2]. AMPK is conserved across essentially all eukaryotic cells and operates through phosphorylation of downstream targets that switch on glucose and fatty acid uptake, mitochondrial biogenesis (via PGC-1\u03B1 activation), and oxidative metabolism [Ref H2, H3]. AMPK also coordinates with hormonal signals at the whole-body level to regulate energy intake and expenditure [Ref H1, H4]."));
children.push(P("Endocrine signals that the AI can direct TIF cells to release for metabolic up-regulation include leptin, FGF21, irisin, and thyroid-stimulating hormone analogues. Each of these activates downstream mitochondrial response through PGC-1\u03B1 and related pathways, producing increased mitochondrial biogenesis and oxidative capacity in target tissues [Ref G2, G4]. These are normal endocrine signals that the body already produces and responds to; the architecture's contribution is AI-directed temporal control of their release rather than introduction of novel signaling."));

children.push(H4("1.5.4 Architectural Application"));
children.push(P("The metabolic up-regulation pathway operates as the fourth power source through the following loop: the AI senses substrate energy state through Channel A telemetry; when piezoelectric output is insufficient, wireless charging is unavailable, and storage reserves are drawn down, the AI directs TIF cells to release metabolic up-regulation signals (leptin, FGF21, irisin, or analogous PGC-1\u03B1 activators) at controlled concentrations; the body responds by mobilizing energy reserves and increasing mitochondrial activity through PGC-1\u03B1 and AMPK-mediated pathways; engineered cells co-located with mitochondria-rich populations harvest a fraction of the up-regulated electron flow through microbial EET machinery; harvested electrons enter the substrate's electrical network as supplementary power."));
children.push(P("The host-side experience of this state is a felt cost: elevated metabolic rate, increased core body temperature, increased hunger, and over time increased caloric requirements to sustain the up-regulation. This is the first power source in the architecture that imposes a felt cost on the host and the architecture explicitly acknowledges this in its specification rather than treating it as a hidden cost."));

children.push(H4("1.5.5 Upper Bound Constraints"));
children.push(P("Healthy human metabolism can sustain elevated rates for finite durations. Sustained hypermetabolic states have established pathological consequences including thyroid dysfunction, cardiac strain, oxidative damage from chronic high metabolism, muscle wasting if caloric intake does not keep pace, and cognitive impairment from sustained hyper-metabolic state. The architecture's use of metabolic up-regulation must respect these limits. Extended emergency operation that requires sustained mitochondrial overdrive cannot be permitted to extend indefinitely without damaging the host."));
children.push(P("The architecture commits to a designed maximum duration on full mitochondrial mobilization, after which the AI throttles its own operation rather than continuing to draw on host metabolism. The specific maximum duration requires empirical determination based on the host's individual metabolic profile and the rate of mitochondrial draw being applied. This is identified as an open parameter requiring per-host calibration prior to deployment of the metabolic source as part of the active power architecture."));

children.push(H3("1.6 Switching Logic Across All Four Sources"));
children.push(P("The complete energy management state machine has four sources with documented switching rules:"));

